<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['Student']);
$user=current_user();$requestId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
$st=$pdo->prepare('SELECT s.*,u.name,u.email,d.name department_name,cr.status FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN departments d ON d.id=s.department_id JOIN clearance_requests cr ON cr.student_id=s.id WHERE s.user_id=? AND cr.id=?');$st->execute([$user['id'],$requestId]);$data=$st->fetch();
if(!$data||$data['status']!=='Approved'){http_response_code(404);exit('Approved certificate not found.');}
$cert=$pdo->prepare('SELECT * FROM certificates WHERE request_id=?');$cert->execute([$requestId]);$certificate=$cert->fetch();
$college=$pdo->prepare('SELECT setting_value FROM system_settings WHERE setting_key=?');$college->execute(['college_name']);$collegeName=$college->fetchColumn()?:'CLEARX College';
$pageTitle='No Due Certificate | CLEARX';?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width"><title><?=e($pageTitle)?></title><link rel="stylesheet" href="../assets/css/style.css"><style>@media print{body{background:white}.no-print{display:none}.certificate{margin:20px auto}}</style></head><body style="background:#eef2f7;padding:30px"><button class="btn btn-primary no-print" onclick="window.print()" style="margin:0 0 18px">Print / Save as PDF</button><main class="certificate"><h3><?=e($collegeName)?></h3><h1>No Due Certificate</h1><p>This is to certify that</p><h2><?=e($data['name'])?></h2><p>USN: <b><?=e($data['usn'])?></b> &nbsp; | &nbsp; Department: <b><?=e($data['department_name'])?></b></p><p>has satisfactorily completed all required clearances for Semester <?=e($data['semester'])?>.</p><div class="certificate-meta"><div><b>Certificate ID</b><p class="certificate-id"><?=e($certificate['certificate_id'])?></p></div><div><b>Issue Date</b><p><?=e(date('d F Y',strtotime($certificate['issue_date'])))?></p></div></div><img class="certificate-qr" alt="Certificate verification QR" src="https://api.qrserver.com/v1/create-qr-code/?size=110x110&data=<?=rawurlencode($certificate['verification_url'])?>"><p><b>Scan to verify certificate</b></p><span class="verification-status"><i class="fa-solid fa-circle-check"></i> Verified &amp; Approved</span><p style="margin-top:35px"><b><?=e($pdo->query("SELECT setting_value FROM system_settings WHERE setting_key='principal_name'")->fetchColumn())?></b><br>Principal</p></main></body></html>
